# Generated by the release workflow of the source repo; edits here are overwritten.
# A cask, not a formula: Homebrew treats a formula without bottles as a build from source and
# refuses to install it when Xcode or the Command Line Tools are missing or too old, although
# nothing is compiled. Casks are for ready-made apps and skip those checks.
cask "lilbro" do
  arch arm: "arm64", intel: "x64"

  version "0.1.15"
  sha256 arm:   "a9ad21090a1f2d1c3d666fe862b4c44374c7ce76ba11d8b4a6644117da9e1c67",
         intel: "fe25bf41f96e6665deadd771faecd2185c53c32e3aa327b792ca2e8243b50f48"

  url "https://github.com/rajaryan12123/homebrew-lilbro/releases/download/v#{version}/lilbro-mac-#{arch}.tar.gz"
  name "lilbro"
  desc "Use Claude Code from Telegram or Slack"
  homepage "https://github.com/rajaryan12123/homebrew-lilbro"

  binary "lilbro/bin/lilbro"

  # Homebrew marks the download as "from the internet", so macOS asks "Are you sure you want to
  # open it?" the first time each new version starts, and the bot stays down until someone clicks
  # Open at the Mac. Homebrew has already checked the download's sha256.
  postflight do
    system_command "/usr/bin/xattr", args: ["-dr", "com.apple.quarantine", "#{staged_path}/lilbro"]
  end

  caveats <<~EOS
    Connect Telegram and/or Slack and start it:
      lilbro setup
    To update: brew update && brew upgrade lilbro, then restart it:
      lilbro restart
    To remove it, first: lilbro uninstall
  EOS
end
